head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gBelngDepCd = js_belngdepcd;
scwin.gDutyGrp = js_gduty;
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보 
scwin.gEmpNo = js_emp_no; // 세션정보 
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03
scwin.gLdMktTpCd = js_market; // 로그인사용자의 시장구분

scwin.vScrenID = 'ULDSTF10104.xml';

// 부모창(목록검색)의 접수번호
//var gAcptNo = frame.Provider("/").gAcptNo;
scwin.gAcptNo = $c.frame.path("../frame_head").scwin.gAcptNo;
scwin.gSndlocTp = $c.frame.path("../frame_head").gSndlocTpCd;
scwin.gProcsStatCd = $c.frame.path("../frame_head").scwin.gProcsStatCd; // 처리상태
scwin.gNxtTpCd = $c.frame.path("../frame_head").scwin.gNxtTpCd; // 익일당일여부
scwin.gDoc_LdMktTp = $c.frame.path("../frame_head").scwin.gDoc_LdMktTp;
scwin.gDisclsAcptTpCd = $c.frame.path("../frame_head").scwin.gDisclsAcptTpCd; // 공시접수유형
scwin.gDisclsTrnsmTpCd = $c.frame.path("../frame_head").scwin.gDisclsTrnsmTpCd; // 전송구분
scwin.gDelayYn = $c.frame.path("../frame_head").scwin.gDelayYn; // 처리지연 상태여부
scwin.gDelayFormYn = $c.frame.path("../frame_head").scwin.gDelayFormYn;
scwin.gMainFormCd = $c.frame.path("../frame_head").scwin.gMainFormCd; //서식코드 : 확인절차 대상법인 조치안내(20151231)

//연계공시개발
scwin.gHdcomLnkDisclsYn = $c.frame.path("../frame_head").scwin.gHdcomLnkDisclsYn;
scwin.gHdcomDisclsProcsStatCd = $c.frame.path("../frame_head").scwin.gHdcomDisclsProcsStatCd;
scwin.gSubcomDisclsProcsStatCd = $c.frame.path("../frame_head").scwin.gSubcomDisclsProcsStatCd;
scwin.gSubcomNxtddTddTpCd = $c.frame.path("../frame_head").scwin.gSubcomNxtddTddTpCd;
//연계공시개발

scwin.gTrdHaltMsg = $c.frame.path("../frame_head").scwin.gTrdHaltMsg;
scwin.gFormWarnContn = $c.frame.path("../frame_head").scwin.gFormWarnContn; //공동공시 유의사항
scwin.gAtsIsuYn = $c.frame.path("../frame_head").scwin.gAtsIsuYn; //ATS 거래종목 여부
scwin.gMktclsYn = $c.frame.path("../frame_head").scwin.gMktclsYn; //장종료 여부(18:00~20:00)
scwin.gAtsTrnsmYn = $c.frame.path("../frame_head").scwin.gAtsTrnsmYn; //거래정지 해당여부(ATS 전송여부)
scwin.gAtsTrnsmRsltCd = $c.frame.path("../frame_head").scwin.gAtsTrnsmRsltCd; //ATS 전송 결과(S_성공,E_실패,E1_실패(공시뷰어를 닫지 않은 경우))
scwin.gBatchReservYn = $c.frame.path("../frame_head").scwin.gBatchReservYn; //예약공시 여부(Y^20시이전,N^20시이후,^대상X)
scwin.gMsgSum = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_showOptButton = function() {
    // 1. 승인 및 유보 버튼 생성
    if (scwin.gProcsStatCd == '10') {
        // 검토상태			
        $c.stf.showObj(img_approval, true); // 승인 show
        $c.stf.showObj(img_reserve, false); // 유보 hidden

    } else if (scwin.gProcsStatCd == '20') {
        // 보류상태
        $c.stf.showObj(img_approval, false); // 승인 hidden
        $c.stf.showObj(img_reserve, true); // 유보 show

    } else {
        $c.stf.showObj(img_approval, false); // 승인 hidden
        $c.stf.showObj(img_reserve, false); // 유보 show			
        $c.stf.showObj(img_review, false); // 재검토요구  hidden		

    }
    if (scwin.gSndlocTp == '90') {
        // 지주회사연계공시
        img_reserve.src = "../img/btn_reserve_d.gif";
        img_reserve.setDisabled(true);
        img_review.src = "../img/btn_review_d.gif";
        img_review.setDisabled(true);
    }

    // 2. 우편함 공시일때		
    if (scwin.gNxtTpCd == 2 || scwin.gNxtTpCd == 4) {
        // 당일 또는 익일처리일때			1^당일전송,2^비전송(코스콤제외),4^익일전송,5^익일처리
        rdo_trnsmtp.Format = "1^당일전송,2^비전송(코스콤제외)";
        rdo_trnsmtp.style.backgroundColor = "#d9e9fc";
        rdo_trnsmtp.Reset();
    } else {
        // 익일 -> 우편함으로 들어온경우

        if (scwin.gDoc_LdMktTp == 2) {
            // 코스닥일때
            rdo_trnsmtp.Format = "1^당일전송,2^비전송(코스콤제외),4^익일전송,5^익일처리";
            rdo_trnsmtp.style.backgroundColor = "#d9e9fc";
            rdo_trnsmtp.Reset();
        } else if (scwin.gDoc_LdMktTp == 1) {
            // 유가일때
            rdo_trnsmtp.Format = "1^당일전송,2^비전송(코스콤제외),4^익일전송";
            rdo_trnsmtp.style.backgroundColor = "#d9e9fc";
            rdo_trnsmtp.Reset();
        } else if (scwin.gDoc_LdMktTp == 4) {
            // 채권일때 (2011.09.20)
            rdo_trnsmtp.Format = "1^당일전송,2^비전송(코스콤제외),4^익일전송";
            rdo_trnsmtp.style.backgroundColor = "#d9e9fc";
            rdo_trnsmtp.Reset();
        } else {
            rdo_trnsmtp.Format = "1^당일전송,2^비전송(코스콤제외),4^익일전송";
            rdo_trnsmtp.style.backgroundColor = "#d9e9fc";
            rdo_trnsmtp.Reset();
        }
    }

    // 3. 검토단계에 처리했던 전송구분코드
    if (scwin.gNxtTpCd == 2 || scwin.gNxtTpCd == 4) {
        // 당일 또는 익일처리일때	
        if (scwin.gDisclsTrnsmTpCd == '2') {
            // 비전송
            $c.stf.setObjectValue(rdo_trnsmtp, '2');
        } else {
            $c.stf.setObjectValue(rdo_trnsmtp, '1');
        }
    } else if (scwin.gNxtTpCd == 3) {
        $c.stf.setObjectValue(rdo_trnsmtp, '1');
    } else {
        $c.stf.setObjectValue(rdo_trnsmtp, '4');
    }
    // 사유지정 버튼 
    if (js_market == '1') {
        //  유가일때				
        $c.stf.showObj(img_rsn, false);
    } else {
        $c.stf.showObj(img_rsn, true);
    }

    //ATS 전송여부 버튼
    if (scwin.gSndlocTp == '90') {
        // 지주회사연계공시의 경우 ATS전송대상에서 제외하도록
        scwin.gAtsIsuYn = 'N';
    }

    //if (gAtsIsuYn == 'Y' && gMktclsYn == 'Y' && (gBelngDepCd == '2600' || gBelngDepCd == '3400')) {  //ATS 거래종목 여부 & 장종료 여부(18:00~20:00) & 공시팀
    if (scwin.gAtsIsuYn == 'Y' && scwin.gMktclsYn == 'Y') {
        //ATS 거래종목 여부 & 장종료 여부(18:00~20:00)
        panel_ATS.style.visibility = "";

        //ATS 전송여부 빈칸인 경우 검토/승인 버튼 비활성화
        if ($c.stf.getObjectValue(cmb_ATS_TRNSM_YN) == '') {
            scwin.fn_DisableObj("approval");
        }
    } else {
        panel_ATS.style.visibility = "hidden";
    }
};
scwin.fn_EnableObj = function(name) {
    var obj = eval("img_" + name);
    obj.src = "../img/btn_" + name + ".gif";
    obj.setDisabled(false);
};
scwin.fn_DisableObj = function(name) {
    var obj = eval("img_" + name);
    obj.src = "../img/btn_" + name + "_d.gif";
    obj.setDisabled(true);
};


/*
 * 로그인 사용자정보로 공시처리가능여부 체크
 *  => 팀장(or 부서장)은 팀구분은 없다.
 */
scwin.fn_getApprvProcButtonYN = function() {
    var url = "/Viewer.do?method=getProcBtnShowYn" + "&inputMessageId=VIEWER_PROCBTNSHOWYN_INOUT" + "&outputMessageId=VIEWER_PROCBTNSHOWYN_INOUT" + "&ACPT_NO=" + scwin.gAcptNo + "&DUTY_GRP_TP=" + scwin.gDutyGrp + "&DEP_CD=" + scwin.gDepCd;
    dts_btnshow.DataID = encodeURI(url);
    dts_btnshow.reset();
};


// 책임자처리시 :  처리버튼 생성여부 
scwin.fn_showApprvProcButton = function(pDutyProcYn, pGrnlProcYn, pCloseYn) {
    /*
    alert("gAcptNo-->"+gAcptNo);
    alert("gJobTitle-->"+gJobTitle);
    alert("pCloseYn-->"+pCloseYn);
    alert("gDutyYn-->"+gDutyYn);
    alert("pDutyProcYn-->"+pDutyProcYn); 
    alert("gDutyChrg-->"+gDutyChrg); 
    */

    if (scwin.gAcptNo != '') {
        // 가져온접수번호가 있으면 처리함.
        // 팀장 및 부서장 권한일때만 보임, 팀장  : 09,   부서장: 40, 팀원: 03
        // 책임자당번 추가 2011.06.30
        //if (gJobTitle == '09' || gJobTitle == '40' || gDutyYn == 'Y' || gDutyChrg == 'Y') {
        if (scwin.gJobTitle != '40' && (scwin.gJobTitle == '09' || scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y')) {
            //부서장권한 제거 2013.03.26
            // 마감전일때
            if (pCloseYn == 'N') {
                if (scwin.gFormWarnContn != "") {
                    label_WARN_CONTN.childNodes[0].innerText = scwin.gFormWarnContn;
                }

                // 로그한 사용자가 당번이면서 접수문서가 당번그룹에 해당할 경우
                if (pDutyProcYn == 'Y') {
                    // 패널라운드 처리	
                    $c.libRoundPanel.PanelToGroupBox(panel_12);
                    $c.stf.showObj(panel_1, true);
                } else {
                    /*
                    // 일반사용자이면서 접수문서가 소속부서에 해당할 경우
                    if (pGrnlProcYn == 'Y') {
                    	// 패널라운드 처리	
                    	PanelToGroupBox(panel_1);	
                    	showObj(panel_1, true);
                    } else {
                    	showObj(panel_1, false);
                    }
                    */
                    // 팀장 및 부서장은 모두 부서의 문서를 처리가능하다.
                    $c.libRoundPanel.PanelToGroupBox(panel_12); // 패널라운드 처리		
                    $c.stf.showObj(panel_1, true);
                }
            } else {
                // 마감후일때
                $c.stf.showObj(panel_1, false);
            }
        } else {
            // 팀장이 아닐때
            $c.stf.showObj(panel_1, false);
        }
    }
};




// 처리상태 조회하기
scwin.fn_getProcsSate = function(gAcptNo) {
    var url = "/Viewer.do?method=getDsclProcsStat" + "&inputMessageId=VIEWER_OUT" + "&outputMessageId=VIEWER_OUT" + "&ACPT_NO=" + scwin.gAcptNo;
    dts_procs_stat.DataID = encodeURI(url);
    dts_procs_stat.reset();
    var vPROCS_STAT_CD = dts_procs_stat.getCellData(1, "PROCS_STAT_CD");
    var vPROCS_STAT_NM = dts_procs_stat.getCellData(1, "PROCS_STAT_NM");
    var vPROCS_DDTM = dts_procs_stat.getCellData(1, "PROCS_DDTM");
    var vBLOCK_YN = dts_procs_stat.getCellData(1, "BLOCK_YN");

    //매매거래정지 개시 전 공시배포차단 여부에 해당하면 처리불가 변경 2021.07.16
    if (vBLOCK_YN == 'Y') {
        $c.win.alert(scwin.gTrdHaltMsg);
        return false;
    }
    if (scwin.gProcsStatCd != vPROCS_STAT_CD) {
        $c.win.alert("본 공시가 " + vPROCS_DDTM + "에  이미 [" + vPROCS_STAT_NM + "] 처리가 되었습니다.");
        //fn_CloseParentReload();
        return false;
    } else {
        return true;
    }
};



// 승인(전송)처리하기 
scwin.fn_DsclApproval = function() {
    // 전송구분 셋팅 :1^당일전송,2^비전송(코스콤제외),4^익일전송,5^익일처리
    var vTrnsmtp = $c.stf.getObjectValue(rdo_trnsmtp);
    var vMsg = "";
    var vMsgTail = "승인처리 하시겠습니까?";
    if (scwin.gSndlocTp == '90') {
        // 유가이고 지주회사연계공시일때
        //if ( gDoc_LdMktTp == 1  && gSndlocTp == '90') {	// 유가이고 지주회사연계공시일때
        if (scwin.gSubcomDisclsProcsStatCd == '35' && vTrnsmtp != '4') {
            $c.win.alert("자회사연계공시가 익일승인처리되어 지주회사 연계공시도 익일자동전송으로 처리하셔야 됩니다.");
            return false;
        }
        if (scwin.gSubcomNxtddTddTpCd == '4' && vTrnsmtp != '5') {
            $c.win.alert("자회사연계공시가 익일처리상태이므로 지주회사 연계공시도 익일처리상태로 처리하셔야 됩니다.");
            return false;
        }
    }
    //alert('gHdcomDisclsProcsStatCd'+gHdcomDisclsProcsStatCd);

    if (vTrnsmtp == '1') {
        if ($c.stf.getObjectValue(cmb_ATS_TRNSM_YN) != 'Y') {
            //ATS 전송여부가 전송이 아닐 때
            if (scwin.gNxtTpCd == 2) {
                // 당일	
                vMsg = '당일 ';
            } else if (scwin.gNxtTpCd == 1) {
                // 익일	
                vMsg = '우편함접수 익일자동전송으로 검토완료된 문서입니다.\n ' + ' 승인시 당일전송 됩니다.';
            } else if (scwin.gNxtTpCd == 3) {
                // 익을을 당일로..
                vMsg = '우편함접수 당일전송 문서입니다.\n ' + ' 승인시 당일전송 됩니다.';
            }
        }
    } else if (vTrnsmtp == '2') {
        vMsg = '비전송은 해당 공시가 한국거래소와 금감원으로만 공시되고 코스콤의 Check 단말기로는 공시되지 않습니다.\n';
    } else if (vTrnsmtp == '4') {
        vMsg = '익일자동전송 ';
    } else if (vTrnsmtp == '5') {
        vMsg = '익일처리시에는 익일자동전송이 되지 않습니다.\n';
        vMsgTail = '익일처리 하시겠습니까?';
    }
    /*
    else if (vTrnsmtp == '3') {
    	vMsg ='비공개는  해당 공시가 외부로 공시되지 않습니다.';
    } 
    */
    if (scwin.gAcptNo == '') {
        $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    var vMsgPopup = "\n\n--------------------------------------------------------\n\n";
    var vMsgPopupCnt = 0;

    //확인절차 대상법인 관련 조치 안내 내용 (20151231) 
    //담당팀장의 승인 시 
    if (scwin.gMainFormCd == "99802" || scwin.gMainFormCd == "68052") {
        var gLnkMsg = '';
        if (scwin.gMainFormCd == "99802") {
            //99802 불성실공시지정 
            gLnkMsg = '불성실공시 법인으로';
        } else if (scwin.gMainFormCd == "68052") {
            //68052 관리종목지정
            gLnkMsg = '관리종목으로';
        }
        vMsgPopup += ("◆ 안내 사항 ◆\n\n" + gLnkMsg + " 지정된 법인은 지정일부터 공시내용 확인절차 \n" + "대상법인입니다. 동사에 대한 확인절차 대상법인 지정 조치 \n" + "여부를 반드시 확인하시기 바랍니다.");
        vMsgPopupCnt++;
    }
    if (scwin.gMainFormCd == "68053") {
        vMsgPopup += ("◆ 안내 사항 ◆\n\n" + " 관리종목 지정해제된 법인은 해제된 날로부터 3년이 경과하면\n" + " 공시내용 확인절차 대상법인에서 지정해제 됩니다. 동사에 대한\n" + " 확인절차 대상법인 지정 조치 여부를 반드시 확인하시기 바랍니다.\n" + "*[공시관리]>[공시내용 확인절차 대상]>[확인절차 대상법인]>[대상법인현황]");
        vMsgPopupCnt++;
    }
    if (scwin.gMainFormCd == "99813" || scwin.gMainFormCd == "91813") {
        vMsgPopup += ("◆ 안내 사항 ◆\n\n" + " 상장폐지 사유가 발행한 법인은 사유확인일 익일부터 공시내용\n" + " 확인절차 대상법인입니다. 동사에 대한 확인절차 대상법인 지정\n" + " 조치 여부를 반드시 확인하시기 바랍니다.\n" + " 또한 사유가 해소된 날부터 3년이 경과하면 공시내용 확인절차 대상\n" + " 법인에서 지정해제 됨에 따라 사유가 해소된 날 동사의 확인절차 \n" + " 대상 지정해제예정일 관련사항을 반드시 입력하여 주시기 바랍니다.\n" + "*[공시관리]>[공시내용 확인절차 대상]>[확인절차 대상법인]>[대상법인현황]");
        vMsgPopupCnt++;
    }
    dts_AcptProcs.insertRow();
    dts_AcptProcs.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_AcptProcs.setCellData(1, "TRNSM_TP_CD", vTrnsmtp);
    dts_AcptProcs.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_AcptProcs.setCellData(1, "DISCLS_ACPT_TP_CD", scwin.gDisclsAcptTpCd);
    dts_AcptProcs.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
    if (dts_AcptProcs.getCellData(1, "ACPT_NO") == '') {
        $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    var vMsgSum = '';
    if (vMsgPopupCnt > 0) {
        vMsgSum = (vMsg + vMsgTail + vMsgPopup);
    } else {
        vMsgSum = (vMsg + vMsgTail);
    }
    scwin.gMsgSum = vMsgSum;

    //ATS 전송여부 확인
    if (scwin.gAtsTrnsmRsltCd == "S") {
        scwin.fn_SendApproval("ATS 정상 전송된 공시입니다.\nATS 재전송하지 않습니다.\n" + vMsgSum);
    } else if (scwin.gAtsTrnsmRsltCd == "E") {
        scwin.fn_SendApproval("ATS 수신오류 발생한 공시입니다.\nATS 재전송하지 않습니다.\n" + vMsgSum);
    } else if (scwin.gAtsTrnsmRsltCd == "E1") {
        scwin.fn_SendApproval("ATS 수신오류 발생한 공시입니다.\n" + vMsgSum);
    } else {
        //ATS 전송하지 않은 경우 경우 승인 처리
        if (scwin.fn_CheckATS()) {
            scwin.fn_SendApproval(vMsgSum);
        }
    }
};




//ATS 전송 체크
scwin.fn_CheckATS = function() {
    //alert(gAtsIsuYn + "\n" + gMktclsYn + "\n" + getObjectValue(cmb_ATS_TRNSM_YN) + "\n" + gAtsTrnsmYn);

    //담당자 검토와 거래정지 해당여부 일치 확인
    if (scwin.gAtsIsuYn == 'Y' && scwin.gMktclsYn == 'Y') {
        //ATS 거래종목 여부 & 장종료 여부(18:00~20:00)
        if ($c.stf.getObjectValue(cmb_ATS_TRNSM_YN) != scwin.gAtsTrnsmYn) {
            $c.win.alert("재확인 필요\n담당자와 거래정지 해당여부가 불일치합니다.");
            return false;
        } else {
            //ATS 전송여부 저장에 사용
            dts_AcptProcs.setCellData(1, "ATS_TRNSM_YN", $c.stf.getObjectValue(cmb_ATS_TRNSM_YN));
            if ($c.stf.getObjectValue(cmb_ATS_TRNSM_YN) == 'Y') {
                //ATS 전송여부가 전송일 때
                if (confirm("거래정지 해당을 선택하여 ATS 전문 전송 예정입니다.")) {
                    //if(ex_confirm(1)) {	//거래정지 해당을 선택하여 ATS 전문 전송 예정입니다.
                    //ATS 전송 API 호출
                    scwin.fn_SendATS();
                }
                return false;
            } else if ($c.stf.getObjectValue(cmb_ATS_TRNSM_YN) == 'N') {
                if (confirm("거래정지 미해당을 선택하여 ATS 전문 미전송 예정입니다.")) {
                    //if(ex_confirm(2)) {	//거래정지 미해당을 선택하여 ATS 전문 미전송 예정입니다.
                    return true;
                } else {
                    return false;
                }
            } else {
                $c.win.alert("거래정지 해당여부를 선택해 주세요.");
                return false;
            }
        }
    }
    return true;
};
