scwin.fn_SendATS = function() {
    scwin.fn_showload();

    //var url = "/DisclosureApproval.do?method=sendATS&ACPT_NO=" + gAcptNo + "&SNDLOC_TP_CD=" + gSndlocTp + "&LD_MKT_TP_CD=" + gDoc_LdMktTp +
    var url = "/DisclosureApproval.do?method=sendATS&ACPT_NO=" + scwin.gAcptNo + "&SNDLOC_TP_CD=11&LD_MKT_TP_CD=" + scwin.gDoc_LdMktTp + "&inputMessageId=DSCLPROC_IN&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;

    // 로딩 이미지가 순식간에 나타났다 사라지거나 로딩 이미지가 그려지는 영역은 보여지는데 이미지 자체가 안보이는 경우가 있어서
    setTimeout(function() {
        dts_ATS.DataID = encodeURI(url);
        dts_ATS.reset();
    }, 500);
};
scwin.fn_SendApproval = function(vMsgSum) {
    var sMsg = "";
    var sMethod = "processDisclosureApproval";
    if (scwin.gBatchReservYn == 'Y') {
        //20시 이전 예약공시
        sMsg = '20시 이후에 배포됩니다.(예약공시)\n';
        sMethod = "updateDisclosureBatchReserv";
    } else if (scwin.gBatchReservYn == 'N') {
        //20시 이후 예약공시
        sMsg = '즉시 배포됩니다.\n';
    }
    sMsg += vMsgSum;
    if (confirm(sMsg)) {
        if (scwin.fn_getProcsSate(scwin.gAcptNo) == false) {
            scwin.fn_CloseParentReload();
            return false;
        } else {
            scwin.fn_showload();

            // 로딩 이미지가 순식간에 나타났다 사라지거나 로딩 이미지가 그려지는 영역은 보여지는데 이미지 자체가 안보이는 경우가 있어서
            setTimeout(function() {
                trs_AcptProcs.Action = "/DisclosureApproval.do?method=" + sMethod + "&inputMessageId=DSCLPROC_IN&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&ACPT_NO=" + scwin.gAcptNo;
                trs_AcptProcs.KeyName = "toinb_dataid4";
                trs_AcptProcs.KeyValue = "JSP(I:pInput=dts_AcptProcs)";
                trs_AcptProcs.Post();
            }, 500);
        }
    }
};




