scwin.cmb_ATS_TRNSM_YN_OnSelChange = function() {
    if ($c.stf.getObjectValue(cmb_ATS_TRNSM_YN) == '') {
        scwin.fn_DisableObj("approval");
    } else {
        if (img_approval.getDisabled()) {
            scwin.fn_EnableObj("approval");
        }
        if ($c.stf.getObjectValue(cmb_ATS_TRNSM_YN) == 'Y') {
            //ATS 전송여부가 전송일 때 당일전송 체크
            $c.stf.setObjectValue(rdo_trnsmtp, '1');
            rdo_trnsmtp.setDisabled(true);
        } else {
            rdo_trnsmtp.setDisabled(false);
        }
        rdo_trnsmtp.focus();
    }
};
